import heapq
from sys import stdin

def max_score(N):
    a = list(map(int, stdin.readline().split()))

    # Create two heaps: one for the largest N elements and one for the smallest N elements
    max_heap = []
    min_heap = []

    for i in range(3 * N):
        if len(max_heap) < N:
            heapq.heappush(max_heap, -a[i])
        else:
            if -max_heap[0] > a[i]:
                heapq.heappop(max_heap)
                heapq.heappush(max_heap, -a[i])

        if len(min_heap) < N:
            heapq.heappush(min_heap, a[i])
        else:
            if min_heap[0] < a[i]:
                heapq.heappop(min_heap)
                heapq.heappush(min_heap, a[i])

    # Calculate the sum of the largest N elements and the sum of the smallest N elements
    sum_max = -sum(max_heap)
    sum_min = sum(min_heap)

    # Return the maximum possible score
    return sum_max - sum_min

# Call the function with the input from stdin
if __name__ == "__main__":
    N = int(input())
    print(max_score(N))
